/* Derived gang finances: stash belongs to wealth; vehicles join rating through their Crew. */
(()=>{
'use strict';
const num=value=>{const n=Number(value);return Number.isFinite(n)?n:0};
const flag=value=>value===true||value==='true';
const editionOf=g=>String(g?.edition||g?.edition_slug||'N23').toUpperCase();
// Defaults come from the verified record for the selected edition, never another edition.
function defaults(gOrEdition){
 const ed=String(typeof gOrEdition==='string'?gOrEdition:gOrEdition?.edition||gOrEdition?.edition_slug||'').toLowerCase();
 const rule=key=>(globalThis.RULES_DATA?.coreRules||[]).find(row=>row.source_verified&&String(row.edition_slug||row.edition).toLowerCase()===ed&&row.id===ed+'-core-'+key)?.rule_data;
 const budget=rule('gang-budget'),finances=rule('gang-finances'),whole=value=>Number.isSafeInteger(value)&&value>=0;
 return {startingCredits:whole(budget?.default_starting_credits)?budget.default_starting_credits:null,startingReputation:whole(finances?.starting_reputation)?finances.starting_reputation:null,minimumReputation:whole(finances?.minimum_reputation)?finances.minimum_reputation:0};
}
// The original application's generic create form uses 1000 credits and reputation 1.
// These editable UI defaults do not enable an unverified edition's rule tables.
function creationDefaults(gOrEdition){const verified=defaults(gOrEdition);return {startingCredits:verified.startingCredits??1000,startingReputation:verified.startingReputation??1};}
const active=f=>!!f&&!['Dead','Retired','Enslaved','Captured','Destroyed'].includes(f.status)&&!flag(f.killed)&&!flag(f.retired)&&!flag(f.enslaved)&&!flag(f.captured)&&!flag(f.destroyed);
const qty=x=>Math.max(1,num(x.quantity)||1);
const itemValue=x=>Math.max(0,num(x.ratingCost??x.cost??x.purchaseCost??x.purchase_cost))*qty(x);
const itemsValue=items=>(items||[]).reduce((sum,x)=>sum+itemValue(x),0);
function allVehicles(g){const rows=[...(g?.vehicles||[]),...(g?.fighters||[]).flatMap(f=>f.vehicles||[])];return rows.filter((v,i,a)=>v.id?a.findIndex(x=>x.id===v.id)===i:a.indexOf(v)===i);}
function crewId(v,g){if('fighter_id'in v)return v.fighter_id||'';if(typeof v.crew==='string')return v.crew;const assigned=v.crewId||v.fighterId||v.assignedTo||v.assigned_to||v.crew?.id;if(assigned)return assigned;return (g?.fighters||[]).find(f=>(f.vehicles||[]).some(x=>x===v||x.id&&x.id===v.id))?.id||'';}
function effectValue(e){return num(e?.creditsIncrease??e?.credits_increase??e?.typeSpecificData?.credits_increase??e?.type_specific_data?.credits_increase);}
function vehicleValue(v){if(!v)return 0;const effects=Array.isArray(v.effects)?v.effects:Object.values(v.effects||{}).flat();const seen=new Set();let extra=0;for(const e of [...effects,...(v.hardpoints||[])]){const key=e.id||e;if(seen.has(key))continue;seen.add(key);extra+=effectValue(e);}return Math.max(0,num(v.ratingCost??v.cost)+itemsValue(v.equipment)+(v.ratingCost==null?extra:0));}
function fighterValue(g,f,equipmentOverride){if(!f)return 0;const vehicles=editionOf(g)==='N23'?allVehicles(g).filter(v=>crewId(v,g)===f.id&&active(v)).reduce((sum,v)=>sum+vehicleValue(v),0):0;return Math.max(0,num(f.ratingCost??f.cost)+itemsValue(equipmentOverride??f.equipment)+vehicles);}
function allianceTithe(g){const key=g?.allianceId||g?.alliance_id;if(!key)return 0;const catalog=typeof RULES_DATA==='object'?RULES_DATA.alliances||[]:[],row=catalog.find(x=>x.id===key);return Math.max(0,num(row?.tithe_cost??g?.allianceTithe??g?.alliance?.tithe_cost));}
function stashValue(g){return itemsValue(g?.stash);}
function unassignedVehiclesValue(g){if(editionOf(g)!=='N23')return 0;return allVehicles(g).filter(v=>active(v)&&!(g?.fighters||[]).some(f=>f.id===crewId(v,g))).reduce((sum,v)=>sum+vehicleValue(v),0);}
function gangSize(g){return (g?.fighters||[]).filter(active).length;}
function ratingFor(g){return (g?.fighters||[]).filter(active).reduce((sum,f)=>sum+fighterValue(g,f),0)+allianceTithe(g);}
function wealthFor(g){return ratingFor(g)+Math.max(0,num(g?.credits))+stashValue(g)+unassignedVehiclesValue(g);}
function wealthRows(g){return [{label:'Gang Rating',value:ratingFor(g)},{label:'Credits',value:Math.max(0,num(g?.credits))},{label:'Stash',value:stashValue(g)},...(editionOf(g)==='N23'?[{label:'Vehicles (without crew)',value:unassignedVehiclesValue(g)}]:[])];}
function subtypeLabels(f){const labels=f.subtypes||f.fighter_subtypes||(f.subtype?[f.subtype]:f.type?[f.type]:[]);return Array.isArray(labels)?labels.map(String):[];}
function compositionRows(g){const rank=editionOf(g)==='N26'?['leader','champion','prospect','specialist','ganger','juve','pet','brute','hanger-on','beast','loner']:['leader','champion','prospect','specialist','ganger','juve','crew','exotic beast','brute','exotic beast specialist'],counts=new Map();for(const f of (g?.fighters||[]).filter(active)){const subs=subtypeLabels(f),label=`${f.type||f.fighter_type||'Unknown Type'} (${subs.length?subs.join(', '):'*'})`,sort=Math.min(99,...subs.map(x=>{const idx=rank.indexOf(x.toLowerCase());return idx<0?99:idx}));const old=counts.get(label);counts.set(label,{label,value:(old?.value||0)+1,rank:sort});}return [...counts.values()].sort((a,b)=>a.rank-b.rank||a.label.localeCompare(b.label));}
rating=ratingFor;
globalThis.wealth=wealthFor;
function parse(html){const holder=document.createElement('div');holder.innerHTML=html;return holder;}
function breakdownButton(label,value,kind,g){return `<button type="button" class="fin-stat" data-finance="${kind}" data-gang="${esc(g.id)}" aria-haspopup="true" aria-expanded="false">${label}: <strong>${fmt(value)}</strong></button>`;}
const oldGangTopFinance=gangTop;gangTop=function(g){const box=parse(oldGangTopFinance(g)),facts=box.querySelector('.entity-facts');if(facts){for(const child of [...facts.children]){const label=child.textContent.trim();if(/^Wealth:/.test(label))child.outerHTML=breakdownButton('Wealth',wealthFor(g),'wealth',g);else if(/^Gang Size:/.test(label))child.outerHTML=breakdownButton('Gang Size',gangSize(g),'composition',g);else if(/^Trade Points:/.test(label)&&editionOf(g)==='N23')child.remove();}}return box.innerHTML;};
if(typeof gangResourceSummary==='function'){const before=gangResourceSummary;gangResourceSummary=function(g){const box=parse(before(g));for(const row of box.querySelectorAll('.match-stats>div'))if(row.querySelector('small')?.textContent==='Wealth')row.querySelector('strong').textContent=fmt(wealthFor(g));return box.innerHTML;};}
if(typeof matchGangCard==='function'){const before=matchGangCard;matchGangCard=function(g){return before(g).replace(/Wealth\s+[\d,]+/,'Wealth '+fmt(wealthFor(g))).replace(/\d+ Fighters/,gangSize(g)+' Fighters');};}
if(typeof campaignMain==='function'){const before=campaignMain;campaignMain=function(c){const box=parse(before(c));for(const table of box.querySelectorAll('table')){const headers=[...table.querySelectorAll('thead th')],index=headers.findIndex(th=>th.textContent.trim()==='Wealth');if(index<0)continue;for(const row of table.querySelectorAll('.cp-member-row')){const key=row.querySelector('[data-open-gang]')?.dataset.openGang,g=data.gangs.find(x=>x.id===key);if(g&&row.children[index])row.children[index].textContent=fmt(wealthFor(g));}}return box.innerHTML;};}
if(typeof cpRankings==='function'){const before=cpRankings;cpRankings=function(c){const box=parse(before(c)),members=(c.members||[]).map(m=>data.gangs.find(g=>g.id===m.gangId)).filter(Boolean);let rows=members.map(g=>({gang:g,value:wealthFor(g)})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value),last=-1,rank=0;rows=rows.map((x,i)=>{if(x.value!==last)rank=i+1;last=x.value;return {...x,rank}}).filter(x=>x.rank<=3);let section=[...box.querySelectorAll('.cp-triumph')].find(el=>el.querySelector('h3')?.textContent==='Top Gangs by Wealth');if(rows.length&&!section){section=document.createElement('section');section.className='cp-triumph';const reputation=[...box.children].find(el=>el.querySelector('h3')?.textContent==='Top Gangs by Reputation');if(reputation)box.insertBefore(section,reputation);else box.append(section);}if(section){if(!rows.length)section.remove();else section.innerHTML=`<h3>Top Gangs by Wealth</h3><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Gang</th><th>Type</th><th>Player</th><th>Wealth</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${['','1st','2nd','3rd'][x.rank]||x.rank+'th'}</td><td><button class="btn small" data-open-gang="${esc(x.gang.id)}">${esc(x.gang.name)}</button></td><td>${esc(x.gang.faction)}</td><td>${esc(c.members.find(m=>m.gangId===x.gang.id)?.player||'')}</td><td>${fmt(x.value)}</td></tr>`).join('')}</tbody></table></div>`;}return box.innerHTML;};}
if(typeof cpCrewRows==='function')cpCrewRows=function(g){return (g?.fighters||[]).flatMap(f=>f.loadouts?.length?f.loadouts.map(l=>({key:f.id+'|'+l.id,fighter:f,loadout:l,cost:fighterValue(g,f,(f.equipment||[]).filter(e=>l.equipmentIds?.includes(e.id)))})):[{key:f.id+'|',fighter:f,loadout:null,cost:fighterValue(g,f)}]);};
if(typeof cpCrewRating==='function')cpCrewRating=function(p){const g=data.gangs.find(x=>x.id===p.gangId);return (p.crew||[]).reduce((sum,row)=>{const f=g?.fighters.find(x=>x.id===row.fighterId);if(!f)return sum;const loadout=f.loadouts?.find(l=>l.id===row.loadoutId),equipment=loadout?(f.equipment||[]).filter(e=>loadout.equipmentIds?.includes(e.id)):f.equipment;return sum+fighterValue(g,f,equipment);},0);};
let anchor=null,hideTimer=null;
function closeBreakdown(){clearTimeout(hideTimer);document.querySelector('.fin-popover')?.remove();anchor?.setAttribute('aria-expanded','false');anchor?.removeAttribute('aria-describedby');anchor=null;}
function openBreakdown(button){clearTimeout(hideTimer);if(anchor===button&&document.querySelector('.fin-popover'))return;closeBreakdown();const g=data.gangs.find(x=>x.id===button.dataset.gang);if(!g)return;const kind=button.dataset.finance,rows=kind==='composition'?compositionRows(g):wealthRows(g),title=kind==='composition'?'Gang Composition':'Wealth Breakdown',total=kind==='composition'?gangSize(g):wealthFor(g);anchor=button;button.setAttribute('aria-expanded','true');button.setAttribute('aria-describedby','finance-breakdown');document.body.insertAdjacentHTML('beforeend',`<div class="fin-popover" role="tooltip" id="finance-breakdown"><strong>${title}</strong>${rows.length?rows.map(row=>`<div><span>${esc(row.label)}</span><span>${fmt(row.value)}</span></div>`).join(''):'<p>No fighters</p>'}<div class="fin-total"><span>Total :</span><span>${fmt(total)}</span></div></div>`);const popup=document.querySelector('.fin-popover'),rect=button.getBoundingClientRect();popup.style.left=Math.min(Math.max(8,rect.left+rect.width/2-popup.offsetWidth/2),Math.max(8,innerWidth-popup.offsetWidth-8))+'px';const viewportHeight=window.visualViewport?.height||innerHeight,popupHeight=Math.min(popup.offsetHeight,viewportHeight-16),preferredTop=rect.top-popupHeight-8;popup.style.top=Math.max(8,Math.min(preferredTop>=8?preferredTop:rect.bottom+8,viewportHeight-popupHeight-8))+'px';popup.onmouseenter=()=>clearTimeout(hideTimer);popup.onmouseleave=()=>hideTimer=setTimeout(closeBreakdown,100);}
window.addEventListener('click',event=>{const target=event.target.closest('[data-finance]');if(target){event.preventDefault();event.stopImmediatePropagation();openBreakdown(target);}else if(!event.target.closest('.fin-popover'))closeBreakdown();},true);
document.addEventListener('mouseover',event=>{const target=event.target.closest('[data-finance]');if(target)openBreakdown(target);});
document.addEventListener('mouseout',event=>{const target=event.target.closest('[data-finance]');if(target&&!target.contains(event.relatedTarget))hideTimer=setTimeout(closeBreakdown,100);});
document.addEventListener('focusin',event=>{if(event.target.matches('[data-finance]'))openBreakdown(event.target);});
document.addEventListener('focusout',event=>{if(event.target.matches('[data-finance]'))hideTimer=setTimeout(closeBreakdown,100);});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&anchor){event.preventDefault();event.stopImmediatePropagation();closeBreakdown();}},true);
window.addEventListener('resize',closeBreakdown);window.addEventListener('scroll',event=>{if(!event.target?.closest?.('.fin-popover'))closeBreakdown();},true);
const previousRenderFinance=render;render=function(){closeBreakdown();previousRenderFinance();};
window.MMFinancials={defaults,creationDefaults,rating:ratingFor,wealth:wealthFor,fighterValue,vehicleValue,stashValue,unassignedVehiclesValue,allianceTithe,gangSize,compositionRows,wealthRows,active,crewId};
render();
})();
